from make_items import NCSBN, CDC, TJC, AHA, SSC, ADA, ISMP, CDC_VAX, mcq, bow, matrix, ordered, sata
R=[NCSBN]; C=[CDC,NCSBN]; J=[TJC,NCSBN]; H=[AHA,NCSBN]; S=[SSC,NCSBN]; D=[ADA,NCSBN]; I=[ISMP,NCSBN]; V=[CDC_VAX,NCSBN]

# (area, topic, diff, scenario, question, options, key, why, wrong, refs)
ROWS = [
("management-of-care","charge nurse and a new fever",4,"During rounds the charge nurse learns one client has a new temperature of 39 C and a heart rate of 130. Three other clients are stable and waiting for discharge papers.","Which action does the charge nurse take first?","See the client with fever and tachycardia|Delegate the discharge papers|Finish a supply count|Call the stable clients' families","See the client with fever and tachycardia","A new fever with tachycardia may be sepsis and is assessed before paperwork.","Discharge papers, a supply count, and family calls are not the unstable client.",R),
("management-of-care","refusal of blood",5,"A capacitated client who is a Jehovah's Witness is bleeding and refuses packed red cells. The client understands the risk of death. The surgeon asks the nurse to persuade the client to accept blood.","Which response is appropriate?","Support the refusal and ask the surgeon about alternatives the client would accept|Tell the client the refusal is not allowed in this hospital|Hang the blood while the client is looking away|Ask the family to override the refusal","Support the refusal and ask the surgeon about alternatives the client would accept","A capacitated refusal of blood is honored. The nurse can help seek acceptable alternatives.","Forcing blood, hiding the transfusion, or a family override ignores the client's decision.",R),
("management-of-care","against medical advice form",3,"A capacitated client is leaving against advice. The client will not sign the form.","What does the nurse do?","Keep the client until the form is signed|Document the refusal to sign, the teaching, and the departure|Refuse to give any discharge instructions|Call security to block the exit","Document the refusal to sign, the teaching, and the departure","The form is evidence, not a requirement that traps the client. The nurse still documents and teaches.","Holding the client, withholding instructions, or blocking the door is not how a capacitated departure works.",R),
("management-of-care","scope of a phone order",4,"A provider gives a telephone order for morphine in milligrams but does not state the route. The nurse reads the order back without the route and the provider says yes.","Which action is safe?","Write the route the unit usually uses|Do not give the drug until the route is stated and read back|Ask another nurse to choose the route|Give it orally because that is safest","Do not give the drug until the route is stated and read back","A telephone order needs drug, dose, and route read back. A usual route is not an order.","Guessing the route or choosing oral without an order is a medication error.",I),
("management-of-care","visitor and infection",4,"A visitor with a draining wound on the hand wants to hold a newborn. The visitor will not cover the wound.","What does the nurse do?","Allow the visit because family bonding comes first|Stop the visit until the wound is covered or the visitor leaves the nursery area|Give the visitor the baby and document the wound|Ask the visitor to use only one hand","Stop the visit until the wound is covered or the visitor leaves the nursery area","An uncovered draining wound is an infection risk to a newborn. Bonding does not override that.","Allowing the hold or a one-hand compromise still exposes the infant.",C),
("safety-infection","protective environment",5,"A client has severe neutropenia after chemotherapy. A roommate with a cough is being admitted to the same double room.","Which assignment does the nurse challenge?","Place the coughing client in a different room|Keep them together to save a private room|Turn off the neutropenic client's positive-pressure ventilation|Allow fresh flowers in the neutropenic room","Place the coughing client in a different room","A neutropenic client is protected from people with infections. A coughing roommate is the wrong assignment.","Sharing the room, stopping protective airflow, or adding flowers increases infection risk.",C),
("safety-infection","latex allergy",4,"A client reports a latex allergy with past lip swelling after a dental dam. The client is going to surgery.","Which preparation is required?","Use latex-free gloves and equipment and notify the operating room|Use powdered latex gloves because powder reduces allergy|Schedule the client after all latex cases without cleaning the room|Document the allergy and take no other step","Use latex-free gloves and equipment and notify the operating room","A systemic latex history means latex-free supplies and a notified team.","Powdered latex, an uncleaned room, or documentation alone leaves exposure in place.",J),
("safety-infection","radiation implant",4,"A client has a sealed cervical radiation implant. The nurse is organizing care and visitors.","Which plan is appropriate?","Limit time near the client, keep distance, and use shielding as directed|Encourage children to sit on the bed|Assign a pregnant nurse for the full shift|Leave the implant in a shared bathroom if it dislodges","Limit time near the client, keep distance, and use shielding as directed","Time, distance, and shielding reduce exposure. Children and pregnant staff are not placed close.","Bedside visits by children, a pregnant nurse for the shift, or a loose implant in a bathroom spread radiation.",J),
("safety-infection","chemotherapy spill",4,"A small puddle of IV chemotherapy is on the floor. The nurse is the first person there.","What is the first action?","Wipe it with a dry tissue and throw it in the regular trash|Keep people away and use the chemo spill kit|Mop it into the sink|Cover it with a client blanket","Keep people away and use the chemo spill kit","A chemo spill is contained with the designated kit, not household cleanup.","A tissue, a sink, or a blanket spreads the drug and exposes skin.",I),
("safety-infection","restraint order renewal",4,"Bilateral wrist restraints were applied at 0200 with an order. It is now 1000 and the client is calm. The nurse is evaluating the restraints.","Which action is appropriate?","Leave them on until tomorrow's order|Remove them if the client no longer needs them and get a new order before any reapplication|Tie them tighter so the client stays calm|Document that restraints do not need reassessment","Remove them if the client no longer needs them and get a new order before any reapplication","Restraints are removed as soon as the behavior allows. A new order is required to restart them.","Leaving them all day, tightening them, or skipping reassessment continues an unnecessary restraint.",J),
("basic-care-comfort","dysphagia diet",5,"A client with a stroke coughs when given thin water. The speech therapist has not cleared a diet. The tray has regular liquids.","Which feeding decision does the nurse make?","Give thin water slowly|Keep the client NPO for oral intake until a swallow evaluation|Start a regular diet because the client is hungry|Give the liquids through a straw","Keep the client NPO for oral intake until a swallow evaluation","Coughing with thin liquids is aspiration risk. Oral intake waits for a swallow study.","Slow thin water, a regular diet, or a straw still sends liquid toward the airway.",R),
("basic-care-comfort","pressure injury turn",4,"A client with a stage 2 pressure injury on the sacrum is supine. The injury is from moisture and pressure.","Which repositioning plan is appropriate?","Turn at least every 2 hours and keep pressure off the sacrum|Leave the client supine so the dressing is not disturbed|Massage the reddened sacrum|Sit the client in a chair for 6 hours without a shift","Turn at least every 2 hours and keep pressure off the sacrum","Pressure is relieved by turning and offloading. The dressing is not a reason to stay on the wound.","Staying supine, massage, or a long unrelieved sit worsens the injury.",R),
("basic-care-comfort","oxygen device",4,"A client with chronic carbon dioxide retention is somnolent after a family member turned the nasal cannula from 2 L to 8 L. The respiratory rate is 8.","What does the nurse do first?","Leave the oxygen at 8 L because more is better|Reduce the flow toward the prescribed rate and stimulate the client, and support breathing if it does not improve|Turn the oxygen off completely and leave the room|Give a sedative for the sleepiness","Reduce the flow toward the prescribed rate and stimulate the client, and support breathing if it does not improve","Too much oxygen can depress the drive in a retainer. The nurse corrects the flow and stays for the breathing.","Leaving 8 L, walking away with oxygen off, or adding a sedative worsens hypoventilation.",R),
("basic-care-comfort","tube feeding residual",4,"A client receiving continuous tube feeding has a gastric residual of 400 mL and new abdominal distension and nausea. The last residual was 40 mL.","Which action does the nurse take?","Increase the feeding rate|Stop the feeding and notify the provider about the high residual and symptoms|Discard the residual and restart at the same rate without telling anyone|Lay the client flat and continue the feeding","Stop the feeding and notify the provider about the high residual and symptoms","A jump in residual with distension and nausea means the feeding is not moving. It is held and reported.","Speeding the feeding, restarting quietly, or lying flat increases aspiration risk.",R),
("basic-care-comfort","ostomy pouch",3,"A new colostomy pouch is leaking stool onto the skin. The stoma is pink. The skin is red where stool has sat.","What does the nurse do?","Leave the pouch so the client can learn the leak|Change the pouch, clean the skin, and resize the opening to protect the skin|Cover the leak with tape only|Irrigate the stoma with tap water under pressure","Change the pouch, clean the skin, and resize the opening to protect the skin","Stool on skin causes breakdown. A leaking pouch is changed and fitted.","Leaving it, tape alone, or a forceful irrigation does not protect the skin.",R),
("reduction-risk","chest tube disconnection",5,"A client's chest tube disconnects from the drainage system. The tube is still in the chest. The client is breathing and anxious.","What does the nurse do first?","Clamp the tube and leave for the provider|Place the open end in sterile water to make a water seal while calling for help|Reconnect it to the dirty end on the floor|Pull the tube out","Place the open end in sterile water to make a water seal while calling for help","An open chest tube can let air in. A temporary water seal restores a one-way system.","Clamping, a dirty reconnect, or pulling the tube creates a worse pneumothorax or infection.",J),
("reduction-risk","transfusion reaction",5,"Ten minutes into a red-cell transfusion the client has fever, back pain, and dark urine. Blood pressure is falling.","Which action is first?","Slow the rate and give diphenhydramine|Stop the transfusion and keep the vein open with normal saline|Speed the unit so it finishes|Start the next unit","Stop the transfusion and keep the vein open with normal saline","Fever, pain, dark urine, and hypotension during a transfusion are a hemolytic reaction until proved otherwise. The unit stops.","Slowing, speeding, or hanging another unit keeps incompatible blood running.",J),
("reduction-risk","postoperative bleeding",4,"One hour after abdominal surgery the dressing is saturated and blood is pooling under the client. Heart rate is 122 and blood pressure is 88/54.","What is the nurse's first action?","Reinforce the dressing and reassess in an hour|Stay with the client, apply pressure as appropriate, and activate help for bleeding and shock|Have the client walk to reduce clots|Give the oral pain pill and wait","Stay with the client, apply pressure as appropriate, and activate help for bleeding and shock","Saturated dressings with tachycardia and hypotension are hemorrhage. The nurse stays and gets help.","Waiting an hour, walking, or a pain pill delays resuscitation.",J),
("reduction-risk","wound evisceration",5,"A client coughs and the abdominal incision opens. Bowel is visible on the abdomen.","Which action does the nurse take?","Push the bowel back in|Cover the bowel with sterile saline-moistened gauze and keep the client supine with the knees bent while calling the surgeon|Sit the client up and give a drink|Apply a dry dressing and send the client to the bathroom","Cover the bowel with sterile saline-moistened gauze and keep the client supine with the knees bent while calling the surgeon","Exposed bowel is kept moist and the client is positioned to reduce strain. The surgeon is called.","Pushing bowel back, sitting the client up, or a dry dressing and walking harms the bowel.",J),
("reduction-risk","cast and compartment",5,"A client in a new leg cast has pain out of proportion, pain when the toes are stretched, and a tight cast. Toes are still warm.","What does the nurse do?","Reassure the client that warm toes rule out a problem|Notify the provider immediately for possible compartment syndrome and prepare to loosen the cast|Elevate the leg above the heart and recheck in 4 hours|Give the next dose of opioid and wait","Notify the provider immediately for possible compartment syndrome and prepare to loosen the cast","Pain out of proportion and pain on stretch are compartment syndrome even when pulses and warmth remain.","Reassurance, a long delay, or more opioid alone loses muscle.",J),
("psychosocial","suicide ask directly",4,"A client says, I might be better off if I did not wake up. The client has no prior plan documented.","Which question does the nurse ask next?","Are you thinking about killing yourself, and do you have a plan?|Why would you say something so upsetting?|You do not mean that, do you?|Let us talk about the weather until this passes","Are you thinking about killing yourself, and do you have a plan?","Passive death wishes are followed by a direct question about intent and a plan.","Criticism, a leading denial, or changing the subject misses the risk.",R),
("psychosocial","panic breathing",4,"A client is having a panic attack, breathing 36 times a minute, and saying they are about to die. Oxygen saturation is 99 percent.","Which action does the nurse take?","Tell the client to calm down|Stay with the client and coach slow breaths|Leave to find a pamphlet|Give a detailed lecture on anxiety physiology","Stay with the client and coach slow breaths","Presence and slower breathing reduce the attack. The saturation shows this is not hypoxia.","Ordering calm, leaving, or a lecture does not help in the moment.",R),
("psychosocial","hearing voices",4,"A client with schizophrenia is frightened by voices that say the food is poisoned. The client has not eaten today.","Which response is therapeutic?","The voices are lying and you are being difficult|I do not hear those voices. I will stay with you, and we can look at the sealed tray together|Eat it or you will be discharged|The poison is real and I will throw the tray away","I do not hear those voices. I will stay with you, and we can look at the sealed tray together","The nurse does not argue the hallucination or agree with it. Staying and offering a sealed tray addresses fear and intake.","Calling the client difficult, threatening discharge, or agreeing that the food is poisoned does not help.",R),
("psychosocial","alcohol withdrawal",5,"A client who drinks daily is tremulous, tachycardic, and diaphoretic 16 hours after the last drink. The client is oriented.","Which risk does the nurse prepare for?","A self-limited tremor that needs no medication|Progression to seizure or delirium, so benzodiazepines are given per protocol|Immediate discharge to keep the unit quiet|Restraint without medication","Progression to seizure or delirium, so benzodiazepines are given per protocol","Early withdrawal is treated with benzodiazepines so it does not become seizures or delirium.","Watching only, discharging, or restraining without treatment leaves the seizure risk.",R),
("psychosocial","grief versus depression",4,"Two months after a spouse's death, a client cries when looking at photos but is eating, working, and has no wish to die.","Which interpretation is most appropriate?","This is still consistent with grief|This is major depression that must be treated before any listening|The client should be told to stop crying|The client is psychotic","This is still consistent with grief","Crying with preserved function and no suicidal wish two months later can be grief. The nurse listens and screens, but does not label it psychosis.","Forcing treatment before listening, banning tears, or calling it psychosis misreads grief.",R),
("health-promotion","newborn vaccines",4,"A healthy newborn is going home. The parent asks which vaccine is given before discharge in the United States.","Which vaccine is given?","Hepatitis B|Live measles vaccine|Yearly influenza injection today as the only vaccine|Human papillomavirus vaccine","Hepatitis B","A birth dose of hepatitis B is given before discharge. Measles and HPV are not newborn vaccines.","Measles, influenza as the only shot, and HPV are the wrong timing.",V),
("health-promotion","car seat",3,"Parents of a term newborn are being discharged. They plan to hold the baby in the front seat on the way home.","Which teaching is correct?","Use a rear-facing car seat in the back seat|A front-seat lap hold is fine for the first ride|The baby may ride in a borrowed forward-facing seat today|A car seat is optional under 1 month","Use a rear-facing car seat in the back seat","Newborns ride rear-facing in the back seat, not on a lap in front.","A lap hold, an immediate forward-facing seat, or skipping the seat is unsafe.",R),
("health-promotion","safe sleep",4,"A parent plans to put the newborn prone on a soft pillow with a blanket because the baby sleeps longer that way.","Which teaching does the nurse give?","Place the baby supine on a firm flat surface with no loose bedding|Prone sleep is safer if a monitor is on|A pillow prevents flat head and is required|The parent bed with a heavy blanket is the safest place","Place the baby supine on a firm flat surface with no loose bedding","Supine on a firm surface without soft bedding lowers sudden infant death risk.","Prone sleep, a pillow, or an adult bed with a heavy blanket raises that risk.",R),
("health-promotion","colon screening",3,"A 46-year-old client at average risk asks when colorectal screening should start.","Which answer is consistent with current U.S. guidance?","Start at 45|Wait until 60|Start only after symptoms|Screening is not used in adults","Start at 45","Average-risk colorectal screening now starts at 45.","Waiting until 60, waiting for symptoms, or skipping screening misses the recommendation.",V),
("health-promotion","prenatal folic acid",4,"A client plans to conceive in two months and had a prior pregnancy affected by a neural-tube defect. The current multivitamin has 0.4 mg of folic acid.","Which folic acid plan does the nurse reinforce?","4 mg daily, started before conception|Stay at 0.4 mg|Start 4 mg only after week 12|Replace folic acid with vitamin A megadoses","4 mg daily, started before conception","A prior neural-tube defect calls for a higher folic acid dose before conception, not the routine 0.4 mg.","Staying at 0.4 mg, starting late, or megadose vitamin A is the wrong plan.",V),
("pharmacology-nursing","insulin mixing",4,"A nurse is drawing NPH and regular insulin in one syringe.","Which sequence is correct?","Draw up the cloudy insulin first|Inject air into cloudy, inject air into clear, draw clear, then draw cloudy|Shake the NPH hard, then draw it alone into the regular vial|Mix them in the vial of regular insulin","Inject air into cloudy, inject air into clear, draw clear, then draw cloudy","Clear regular is drawn before cloudy NPH so the NPH vial is not contaminated with regular in the wrong direction. The usual air order is cloudy then clear.","Drawing cloudy first into the syringe, shaking, or mixing inside the regular vial contaminates the vials.",I),
("pharmacology-nursing","digoxin hold",5,"A client's apical pulse is 52 beats per minute. Digoxin is due. The client is nauseated and sees yellow halos.","What does the nurse do?","Give the digoxin with food|Hold the digoxin and notify the provider|Give half the dose|Give the dose and recheck the pulse tomorrow","Hold the digoxin and notify the provider","A slow apical rate plus nausea and visual halos is digoxin toxicity. The dose is held.","Giving it, halving it, or waiting until tomorrow continues toxicity.",I),
("pharmacology-nursing","potassium and a diuretic",4,"A client is due for IV furosemide. The morning potassium is 3.0 mEq/L. The client has muscle cramps.","Which action does the nurse take?","Give the furosemide to treat fluid status first|Hold the furosemide and notify the provider about the potassium|Give the furosemide with orange juice as a substitute for replacement|Double the dose because the potassium is low","Hold the furosemide and notify the provider about the potassium","Loop diuretics lower potassium further. A potassium of 3.0 with cramps is reported and the dose is held.","Giving or doubling the diuretic, or using juice as the only replacement, worsens hypokalemia.",I),
("pharmacology-nursing","vancomycin rate",4,"A client starts IV vancomycin and develops flushing and itching of the face and neck during a fast infusion. Blood pressure is stable.","What does the nurse do?","Speed the infusion so it ends sooner|Stop or slow the infusion and treat the red-man reaction per protocol|Ignore it because the blood pressure is normal|Give the next dose as an IV push","Stop or slow the infusion and treat the red-man reaction per protocol","Flushing during a fast vancomycin infusion is an infusion reaction. The rate is slowed.","Speeding it, ignoring it, or pushing the next dose worsens the reaction.",I),
("pharmacology-nursing","opioid and respiratory rate",5,"A postoperative client received IV morphine 20 minutes ago. The respiratory rate is 7 and the client is hard to arouse.","Which drug does the nurse prepare?","Flumazenil|Naloxone|Vitamin K|Protamine","Naloxone","A slow rate and hard arousal after morphine is opioid toxicity. Naloxone reverses it.","Flumazenil is for benzodiazepines, vitamin K for warfarin, and protamine for heparin.",I),
("physiological-adaptation","anaphylaxis",5,"A client receiving an IV antibiotic develops hives, wheezing, and a blood pressure of 80/40.","Which drug does the nurse give first?","Diphenhydramine only|Intramuscular epinephrine|An oral steroid|A saline flush of the antibiotic line","Intramuscular epinephrine","Wheezing and shock with hives is anaphylaxis. Epinephrine is first.","An antihistamine or steroid alone, or flushing more antibiotic, does not reverse shock.",H),
("physiological-adaptation","chest pain MONA trap",4,"A client has crushing chest pain and oxygen saturation of 98 percent on room air. Aspirin is ordered and has not been given. Oxygen is not ordered.","Which action is appropriate?","Apply a nonrebreather at 15 L because every chest pain gets oxygen|Give the aspirin if there is no allergy, and do not add unneeded high-flow oxygen|Withhold aspirin until after a meal|Have the client walk to reduce the pain","Give the aspirin if there is no allergy, and do not add unneeded high-flow oxygen","Aspirin is given early for suspected acute coronary syndrome. Oxygen is not automatic when saturation is already normal.","High-flow oxygen, delaying aspirin, or walking the client is not the early treatment.",H),
("physiological-adaptation","stroke time",5,"A client has a sudden right arm drift and slurred speech that the spouse says started 40 minutes ago. Glucose is 110 mg/dL.","What does the nurse do first?","Give the client water to see if the speech clears|Activate a stroke response and keep the client NPO|Send the client for a routine clinic visit tomorrow|Lower the head of the bed to flat and start enteral feeding","Activate a stroke response and keep the client NPO","Sudden deficits within a treatment window need an immediate stroke pathway. Nothing is given by mouth until swallowing is safe.","Water, a next-day visit, or feeding risks aspiration and misses the window.",H),
("physiological-adaptation","DKA potassium",5,"A client in diabetic ketoacidosis has a glucose of 480 mg/dL and a pH of 7.15. The potassium result is not back. The electrocardiogram is normal. Insulin is ready.","What does the nurse do about the insulin?","Start the insulin before the potassium is known|Hold the insulin until the potassium is known to be at least 3.3 mEq/L|Give bicarbonate as the only drug|Give a subcutaneous dose and discharge","Hold the insulin until the potassium is known to be at least 3.3 mEq/L","Insulin drives potassium into cells. It is not started until the nurse knows the potassium is not already low.","Blind insulin, bicarbonate alone, or discharge is not how ketoacidosis is opened.",D),
("physiological-adaptation","pulmonary embolism",4,"A postoperative client suddenly cannot breathe, has chest pain, and an oxygen saturation of 86 percent. The calf is swollen.","Which action is first?","Have the client walk the clot out|Sit the client up, give oxygen, and notify the provider for a possible pulmonary embolism|Give a bronchodilator only|Lower the head of the bed and give fluids as the only step","Sit the client up, give oxygen, and notify the provider for a possible pulmonary embolism","Sudden hypoxia, chest pain, and a swollen calf after surgery are embolism until proved otherwise. Oxygen and help come first.","Walking, a bronchodilator alone, or fluids only do not treat the clot or the oxygen.",H),
]

def load():
    for area, topic, diff, scenario, question, options, key, why, wrong, refs in ROWS:
        mcq(area, topic, diff, scenario, question, options.split("|"), key, why, wrong, refs)

load()
